--
-- Table structure for table `word`
--

DROP TABLE IF EXISTS `word`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `word` (
  `word_id` int(11) NOT NULL auto_increment,
  `glyph_id` int(11) NOT NULL,
  `page_number` int(11) NOT NULL,
  `sura_number` int(11) NOT NULL,
  `ayah_number` int(11) NOT NULL,
  `position` int(11) NOT NULL,
  `word_arabic_id` int(11) NOT NULL,
  `word_stem_id` int(11) default NULL,
  `word_lemma_id` int(11) default NULL,
  `word_root_id` int(11) default NULL,
  PRIMARY KEY  (`word_id`),
  UNIQUE KEY `sura_ayah_position_index` (`sura_number`,`ayah_number`,`position`),
  UNIQUE KEY `glyph_unique` (`glyph_id`),
  KEY `page_index` (`page_number`),
  KEY `sura_index` (`sura_number`),
  KEY `sura_ayah_index` (`ayah_number`,`sura_number`),
  KEY `page_ayah_index` (`page_number`,`ayah_number`),
  KEY `word_root_id` (`word_root_id`),
  KEY `word_lemma_id` (`word_lemma_id`),
  KEY `word_stem_id` (`word_stem_id`),
  KEY `word_arabic_id` (`word_arabic_id`),
  CONSTRAINT `word_ibfk_5` FOREIGN KEY (`glyph_id`) REFERENCES `glyph` (`glyph_id`) ON UPDATE CASCADE,
  CONSTRAINT `word_ibfk_1` FOREIGN KEY (`word_root_id`) REFERENCES `word_root` (`word_root_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `word_ibfk_2` FOREIGN KEY (`word_lemma_id`) REFERENCES `word_lemma` (`word_lemma_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `word_ibfk_3` FOREIGN KEY (`word_stem_id`) REFERENCES `word_stem` (`word_stem_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `word_ibfk_4` FOREIGN KEY (`word_arabic_id`) REFERENCES `word_arabic` (`word_arabic_id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=77431 DEFAULT CHARSET=utf8 MIN_ROWS=77430 MAX_ROWS=77430;
/*!40101 SET character_set_client = @saved_cs_client */;

