INSERT INTO `word_translation` VALUES (1,38,1,'In (the) name',0),(2,38,2,'(of) Allah,',0),(3,38,3,'the Most Gracious,',0),(4,38,4,'the Most Merciful.',0),(5,38,5,'All praises and thanks',0),(6,38,6,'(be) to Allah,',0),(7,38,7,'the Lord',0),(8,38,8,'of the universe',0),(9,38,9,'The Most Gracious,',0),(10,38,10,'the Most Merciful.',0),(11,38,11,'(The) Master',0),(12,38,12,'(of the) Day',0),(13,38,13,'(of the) Judgment.',0),(14,38,14,'You Alone',0),(15,38,15,'we worship,',0),(16,38,16,'and You Alone',0),(17,38,17,'we ask for help.',0),(18,38,18,'Guide us',0),(19,38,19,'(to) the path,',0),(20,38,20,'the straight.',0),(21,38,21,'(The) path',0),(22,38,22,'(of) those',0),(23,38,23,'You have bestowed (Your) Favors',0),(24,38,24,'on them,',0),(25,38,25,'not (of)',0),(26,38,26,'those who earned (Your) wrath',0),(27,38,27,'on themselves',0),(28,38,28,'and not',0),(29,38,29,'(of) those who go astray.',0),(30,38,30,'Alif Laam Meem',0),(31,38,31,'That',0),(32,38,32,'(is) the book',0),(33,38,33,'no',0),(34,38,34,'doubt',0),(35,38,35,'in it,',0),(36,38,36,'a Guidance',0),(37,38,37,'for the God-conscious.',0),(38,38,38,'Those who',0),(39,38,39,'believe',0),(40,38,40,'in the unseen,',0),(41,38,41,'and establish',0),(42,38,42,'the prayer,',0),(43,38,43,'and out of what',0),(44,38,44,'We have provided them',0),(45,38,45,'they spend.',0),(46,38,46,'And those who',0),(47,38,47,'believe',0),(48,38,48,'in what',0),(49,38,49,'(is) sent down',0),(50,38,50,'to you',0),(51,38,51,'and what',0),(52,38,52,'was sent down',0),(53,38,53,'from',0),(54,38,54,'before you',0),(55,38,55,'and in the Hereafter',0),(56,38,56,'they',0),(57,38,57,'firmly believe.',0),(58,38,58,'Those',0),(59,38,59,'(are) on',0),(60,38,60,'Guidance',0),(61,38,61,'from',0),(62,38,62,'their Lord,',0),(63,38,63,'and those -',0),(64,38,64,'they',0),(65,38,65,'(are) the successful ones.',0),(66,38,66,'Indeed,',0),(67,38,67,'those who',0),(68,38,68,'disbelieve[d],',0),(69,38,69,'(it) is same',0),(70,38,70,'to them',0),(71,38,71,'whether you warn them',0),(72,38,72,'or',0),(73,38,73,'not',0),(74,38,74,'you warn them,',0),(75,38,75,'not',0),(76,38,76,'they believe.',0),(77,38,77,'Has set a seal',0),(78,38,78,'Allah',0),(79,38,79,'on',0),(80,38,80,'their hearts',0),(81,38,81,'and on',0),(82,38,82,'their hearing,',0),(83,38,83,'and on',0),(84,38,84,'their vision',0),(85,38,85,'(is) a veil.',0),(86,38,86,'And for them',0),(87,38,87,'(is) a punishment',0),(88,38,88,'great.',0),(89,38,89,'And of',0),(90,38,90,'the people',0),(91,38,91,'(are some) who',0),(92,38,92,'say,',0),(93,38,93,'\"We believed',0),(94,38,94,'in Allah',0),(95,38,95,'and in the Day',0),(96,38,96,'[the] Last,\"',0),(97,38,97,'but not',0),(98,38,98,'they',0),(99,38,99,'(are) believers (at all).',0),(100,38,100,'They seek to deceive',0),(101,38,101,'Allah',0),(102,38,102,'and those who',0),(103,38,103,'believe[d],',0),(104,38,104,'and not',0),(105,38,105,'they deceive',0),(106,38,106,'except',0),(107,38,107,'themselves,',0),(108,38,108,'and not',0),(109,38,109,'they realize (it).',0),(110,38,110,'In',0),(111,38,111,'their hearts',0),(112,38,112,'(is) a disease,',0),(113,38,113,'so has increased them',0),(114,38,114,'Allah',0),(115,38,115,'(in) disease;',0),(116,38,116,'and for them',0),(117,38,117,'(is) a punishment',0),(118,38,118,'painful',0),(119,38,119,'because',0),(120,38,120,'they used to',0),(121,38,121,'[they] lie.',0),(122,38,122,'And when',0),(123,38,123,'it is said',0),(124,38,124,'to them,',0),(125,38,125,'\"(Do) not',0),(126,38,126,'spread corruption',0),(127,38,127,'in',0),(128,38,128,'the earth,\"',0),(129,38,129,'they say,',0),(130,38,130,'\"Only',0),(131,38,131,'we',0),(132,38,132,'(are) reformers.\"',0),(133,38,133,'Beware,',0),(134,38,134,'indeed they',0),(135,38,135,'themselves',0),(136,38,136,'(are) the ones who spread corruption,',0),(137,38,137,'[and] but',0),(138,38,138,'not',0),(139,38,139,'they realize (it).',0),(140,38,140,'And when',0),(141,38,141,'it is said',0),(142,38,142,'to them,',0),(143,38,143,'\"Be